<script>
(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // reveal on scroll
  var io = new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target);} });
  },{threshold:.15});
  document.querySelectorAll('.rv').forEach(function(el,i){
    el.style.transitionDelay = (i%3)*90+'ms';
    io.observe(el);
  });

  // progress bars + step rail
  var once = new IntersectionObserver(function(es){
    es.forEach(function(e){
      if(!e.isIntersecting) return;
      if(e.target.id==='bars') e.target.querySelectorAll('i').forEach(function(b){b.style.width=b.dataset.w;});
      if(e.target.id==='rail') e.target.classList.add('go');
      once.unobserve(e.target);
    });
  },{threshold:.4});
  once.observe(document.getElementById('bars'));
  once.observe(document.getElementById('rail'));

  // phone logo reveal
  new IntersectionObserver(function(es,o){ if(es[0].isIntersecting){ es[0].target.classList.add('in'); o.disconnect(); } },{threshold:.4}).observe(document.querySelector('.phone'));

  // tips
  var tips = {
    nut:[
      ['البروتين بكل وجبة','توزيع البروتين على وجباتك (بيض، لبن، بقوليات، سمك، لحوم) بيساعد على الشبع والمحافظة على العضلات.'],
      ['اشرب مي بانتظام','حتى النقص البسيط بالسوائل ممكن يأثر على تركيزك وأدائك بالتمرين. خلّي زجاجة المي قريبة منك.'],
      ['الأكل الحقيقي أول شي','خضار وفواكه وحبوب كاملة وبقوليات بتعطيك ألياف وفيتامينات أكثر من الأكل المصنّع.']
    ],
    fit:[
      ['الانتظام قبل الشدة','٣ تمارين بالأسبوع تلتزم فيهم أحسن من ٦ أيام بتتركهم بعد أسبوعين.'],
      ['زِد الحمل بالتدريج','رفع الوزن أو التكرارات شوي كل فترة هو سر التطور، مع الحفاظ على الشكل الصحيح للتمرين.'],
      ['النوم جزء من الخطة','العضلات بتتعافى وانت نايم. ٧ إلى ٩ ساعات بتفرق بالأداء وبالمزاج.']
    ]
  };
  var tb=document.getElementById('tipbox');
  function show(k){
    tb.innerHTML='';
    tips[k].forEach(function(t){
      var d=document.createElement('div'); d.className='tip';
      var h=document.createElement('h3'); h.textContent=t[0];
      var p=document.createElement('p'); p.textContent=t[1];
      d.appendChild(h); d.appendChild(p); tb.appendChild(d);
    });
  }
  show('nut');
  document.querySelectorAll('.tabs button').forEach(function(b){
    b.addEventListener('click',function(){
      document.querySelectorAll('.tabs button').forEach(function(x){x.setAttribute('aria-selected','false');});
      b.setAttribute('aria-selected','true'); show(b.dataset.t);
    });
  });
})();
</script>
</body>
